// Build the candidate page list per company. Nothing is fetched here.
// Only a handful of conventional paths: this is a research pass, not a crawl.

const PATHS = ['', '/about', '/careers', '/jobs', '/blog', '/engineering'];
const USER_AGENT = 'AiSalesMachineBot/1.0 (+https://github.com/urosorolicki/ai-sales)';

return $input.all().map((item) => {
  const c = item.json;
  const site = typeof c.website === 'string' && /^https?:\/\//i.test(c.website)
    ? c.website.replace(/\/+$/, '')
    : 'https://' + c.domain;

  return {
    json: {
      ...c,
      base_url: site,
      robots_url: site + '/robots.txt',
      candidate_urls: PATHS.map((p) => site + p),
      user_agent: USER_AGENT,
    },
  };
});

// Apply robots.txt. docs/security.md and the WF-02 row in docs/workflows.md both
// require it, and a research bot that ignores robots.txt is the kind of thing
// that gets an IP blocked and a reputation with it.
//
// Longest-match wins between Allow and Disallow, which is what Google and the
// RFC 9309 draft both specify. A missing or unreadable robots.txt means allow:
// that is the documented default, not an assumption.

function parseRobots(text, agent) {
  const groups = [];
  let current = null;
  for (const rawLine of String(text).split(/\r?\n/)) {
    const line = rawLine.replace(/#.*$/, '').trim();
    if (!line) continue;
    const idx = line.indexOf(':');
    if (idx === -1) continue;
    const field = line.slice(0, idx).trim().toLowerCase();
    const value = line.slice(idx + 1).trim();

    if (field === 'user-agent') {
      if (!current || current.rules.length) {
        current = { agents: [], rules: [] };
        groups.push(current);
      }
      current.agents.push(value.toLowerCase());
    } else if ((field === 'allow' || field === 'disallow') && current) {
      current.rules.push({ allow: field === 'allow', path: value });
    }
  }

  const token = agent.split('/')[0].toLowerCase();
  const exact = groups.find((g) => g.agents.includes(token));
  const wildcard = groups.find((g) => g.agents.includes('*'));
  return (exact || wildcard || { rules: [] }).rules;
}

function isAllowed(path, rules) {
  let best = null;
  for (const rule of rules) {
    // An empty Disallow means "allow everything" and matches nothing.
    if (rule.path === '') continue;
    const pattern = rule.path.replace(/\*+$/, '');
    if (!path.startsWith(pattern)) continue;
    if (best === null || pattern.length > best.length) {
      best = { length: pattern.length, allow: rule.allow };
    }
  }
  return best === null ? true : best.allow;
}

const companies = $('Candidate URLs').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const company = companies[i].json;
  const res = $input.all()[i].json ?? {};

  // neverError is on, so a 404 arrives as data, not as an exception. Either way
  // an unreadable robots.txt means no restrictions were published.
  const body = typeof res.data === 'string' ? res.data : '';
  const rules = body ? parseRobots(body, company.user_agent) : [];

  const allowed = [];
  const blocked = [];
  for (const url of company.candidate_urls) {
    const path = url.slice(company.base_url.length) || '/';
    (isAllowed(path, rules) ? allowed : blocked).push(url);
  }

  out.push({
    json: {
      ...company,
      urls: allowed,
      robots_blocked: blocked,
      robots_rules_found: rules.length,
    },
  });
}

return out;

// One item per fetched page arrives here. Group them back into one item per
// company and turn the HTML into something worth sending to a model.
//
// Everything is capped. An unbounded page is an unbounded bill, and a careers
// page with a thousand listings is not more informative than the first slice.

const MAX_CHARS_PER_PAGE = 6000;
const MAX_CHARS_TOTAL = 24000;

function htmlToText(html) {
  return String(html)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<\/(p|div|li|h[1-6]|tr|section|article)>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#0?39;|&apos;/gi, "'")
    .replace(/[ \t ]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();
}

// The HTTP Request node replaces the item json with the response, so the
// company each page belongs to is read back from Split URLs by index. n8n keeps
// one output item per input item here, so the indexes line up.
const pages = $input.all();
const context = $('Split URLs').all();
const byCompany = new Map();

for (let i = 0; i < pages.length; i++) {
  const j = { ...context[i].json, ...(pages[i].json ?? {}) };
  const key = j.company_id;
  if (!key) continue;

  if (!byCompany.has(key)) {
    byCompany.set(key, {
      company_id: j.company_id,
      name: j.name,
      domain: j.domain,
      website: j.website,
      industry: j.industry,
      base_url: j.base_url,
      prior_failures: j.prior_failures ?? 0,
      robots_blocked: j.robots_blocked ?? [],
      sources: [],
      fetch_failures: [],
      sections: [],
    });
  }
  const bucket = byCompany.get(key);

  // An HTTP error or a network failure is evidence of absence, not a crash.
  const res = pages[i].json ?? {};
  const failed = res.error !== undefined || typeof res.data !== 'string' || res.data === '';
  if (failed) {
    const reason = res.error
      ? (typeof res.error === 'string' ? res.error : (res.error.message ?? 'request failed'))
      : 'empty response';
    bucket.fetch_failures.push(j.url + ' (' + reason + ')');
    continue;
  }

  const text = htmlToText(res.data);
  if (text.length < 40) {
    bucket.fetch_failures.push(j.url + ' (no usable text)');
    continue;
  }

  bucket.sources.push(j.url);
  bucket.sections.push('### SOURCE: ' + j.url + '\n' + text.slice(0, MAX_CHARS_PER_PAGE));
}

const out = [];
for (const bucket of byCompany.values()) {
  let material = bucket.sections.join('\n\n');
  let truncated = false;
  if (material.length > MAX_CHARS_TOTAL) {
    material = material.slice(0, MAX_CHARS_TOTAL);
    truncated = true;
  }
  const { sections, ...rest } = bucket;
  out.push({
    json: {
      ...rest,
      material,
      material_chars: material.length,
      material_truncated: truncated,
      pages_fetched: bucket.sources.length,
      // Playwright is not deployed. A page that needs JavaScript to render is
      // recorded as unknown rather than silently treated as empty.
      rendering_unavailable: bucket.sources.length === 0 && bucket.fetch_failures.length > 0,
    },
  });
}

return out;

// Assemble the Anthropic request. The system prompt is read from
// prompts/research.md at runtime (./prompts is mounted read-only at /prompts),
// so that file is the single source of truth and cannot drift from this node.

const MODEL = $env.LLM_MODEL || 'claude-sonnet-5';
const MAX_TOKENS = Number($env.LLM_MAX_TOKENS) || 4096;

// prompts/research.md keeps the system prompt in the first fenced block under
// "## System prompt". Extract exactly that; a heading change must fail loudly
// rather than quietly send the whole markdown file as a prompt.
function extractSystemPrompt(markdown) {
  const section = markdown.split(/^##\s+System prompt\s*$/m)[1];
  if (!section) throw new Error('prompts/research.md: no "## System prompt" heading found');
  const fence = section.match(/```[a-z]*\n([\s\S]*?)\n```/);
  if (!fence) throw new Error('prompts/research.md: no fenced block under "## System prompt"');
  const text = fence[1].trim();
  if (text.length < 200) throw new Error('prompts/research.md: system prompt looks truncated');
  return text;
}

const systemPrompt = extractSystemPrompt($('Prompt To Text').first().json.data);
const material = $('Group Material').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const run = $input.all()[i].json;
  const m = material[i].json;

  const userContent = [
    'Company: ' + m.name,
    'Domain: ' + m.domain,
    'Industry: ' + (m.industry || 'unknown'),
    '',
    m.sources.length
      ? 'The following material was fetched from the company\'s own site. Cite these URLs.'
      : 'No material could be fetched from this company\'s site.',
    '',
    m.material || '(nothing fetched)',
    '',
    '---',
    'Pages that could not be fetched: ' + (m.fetch_failures.length ? m.fetch_failures.join(', ') : 'none'),
    'Pages disallowed by robots.txt: ' + (m.robots_blocked.length ? m.robots_blocked.join(', ') : 'none'),
    m.material_truncated ? 'The material above was truncated at a character limit.' : '',
    '',
    'Return the JSON object described in the system prompt, and nothing else.',
  ].join('\n');

  out.push({
    json: {
      agent_run_id: run.id,
      company_id: m.company_id,
      name: m.name,
      domain: m.domain,
      prior_failures: m.prior_failures,
      sources: m.sources,
      model: MODEL,
      llm_request: {
        model: MODEL,
        max_tokens: MAX_TOKENS,
        // No "temperature": claude-sonnet-5 rejects sampling parameters with a
        // 400. LLM_TEMPERATURE in .env does not apply to this model.
        // No assistant prefill either - also a 400 on this model family.
        system: [
          {
            type: 'text',
            text: systemPrompt,
            // The system prompt is identical for every company in the batch and
            // between runs, so it is worth caching.
            cache_control: { type: 'ephemeral' },
          },
        ],
        messages: [{ role: 'user', content: userContent }],
      },
    },
  });
}

return out;

// Validate the research response against agents/research/schema.json.
// Never throws, never repairs. A response that does not match is an error.

const SERVICES = ['infrastructure_audit', 'devops_improvement_sprint', 'fractional_devops_sre', 'none'];
const SIGNAL_TYPES = [
  'hiring_devops', 'hiring_engineering_growth', 'kubernetes_adoption',
  'cloud_migration', 'infrastructure_scaling', 'reliability_problem',
  'cloud_cost_problem', 'leadership_change', 'funding',
  'technology_announcement', 'other',
];
const REQUIRED = {
  company_summary: 'string', facts: 'array', technology: 'array',
  hiring_signals: 'array', pain_signals: 'array', reasonable_inferences: 'array',
  unknown: 'array', decision_maker_reason: 'string', recommended_service: 'string',
  why_now: 'string', confidence: 'number', sources: 'array',
};

const requests = $('Build Research Request').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const req = requests[i].json;
  const res = $input.all()[i].json ?? {};
  const errors = [];
  const warnings = [];
  let parsed = null;
  let raw = '';
  let usage = null;

  if (res.error !== undefined) {
    const e = res.error;
    errors.push('Anthropic request failed: ' +
      (typeof e === 'string' ? e : (e && e.message) || JSON.stringify(e)));
  } else {
    usage = res.usage ?? null;

    // Guard stop_reason before reading content: a refusal or a truncation both
    // produce content that looks parseable but is not the answer.
    if (res.stop_reason === 'refusal') {
      errors.push('Model refused the request' +
        (res.stop_details && res.stop_details.category ? ' (' + res.stop_details.category + ')' : ''));
    } else if (res.stop_reason === 'max_tokens') {
      errors.push('Response hit max_tokens and is truncated; raise LLM_MAX_TOKENS');
    }

    const blocks = Array.isArray(res.content) ? res.content : [];
    raw = blocks.filter((b) => b && b.type === 'text').map((b) => b.text).join('');

    if (!errors.length) {
      if (!raw.trim()) {
        errors.push('Model returned no text content');
      } else {
        try {
          parsed = JSON.parse(raw);
        } catch (e) {
          errors.push('Response is not valid JSON: ' + e.message);
        }
      }
    }
  }

  if (parsed !== null && (typeof parsed !== 'object' || Array.isArray(parsed))) {
    errors.push('Response is valid JSON but not a JSON object');
    parsed = null;
  }

  if (parsed !== null) {
    for (const key of Object.keys(REQUIRED)) {
      const kind = REQUIRED[key];
      if (!(key in parsed)) { errors.push('Missing required key: ' + key); continue; }
      const v = parsed[key];
      const isArr = Array.isArray(v);
      if (kind === 'array' ? !isArr : (typeof v !== kind || isArr)) {
        errors.push('Key ' + key + ' must be ' + kind + ', got ' + (isArr ? 'array' : typeof v));
      }
    }
    if (typeof parsed.confidence === 'number' &&
        (!Number.isFinite(parsed.confidence) || parsed.confidence < 0 || parsed.confidence > 1)) {
      errors.push('confidence must be between 0 and 1, got ' + parsed.confidence);
    }
    if (typeof parsed.recommended_service === 'string' && !SERVICES.includes(parsed.recommended_service)) {
      errors.push('recommended_service "' + parsed.recommended_service + '" is not in the allowed set');
    }
    if (Array.isArray(parsed.pain_signals)) {
      for (const s of parsed.pain_signals) {
        if (!s || typeof s !== 'object') { errors.push('pain_signals entries must be objects'); break; }
        if (!SIGNAL_TYPES.includes(s.signal_type)) {
          // The signals table has the same CHECK constraint; a bad value here
          // would be a failed insert later, so reject it now.
          errors.push('pain_signals.signal_type "' + s.signal_type + '" is not an allowed signal_type');
        }
      }
    }
  }

  const valid = errors.length === 0;

  // Only signals with real text survive: signals.signal has a non-empty CHECK.
  const signals = valid
    ? parsed.pain_signals
        .filter((s) => typeof s.signal === 'string' && s.signal.trim() !== '')
        .map((s) => ({
          signal_type: s.signal_type,
          signal: s.signal.trim(),
          source: typeof s.source === 'string' ? s.source : '',
          confidence: typeof s.confidence === 'number' ? s.confidence : 0.5,
        }))
    : [];

  if (valid && parsed.pain_signals.length !== signals.length) {
    warnings.push('Dropped ' + (parsed.pain_signals.length - signals.length) + ' pain_signals with empty text');
  }

  out.push({
    json: {
      agent_run_id: req.agent_run_id,
      company_id: req.company_id,
      name: req.name,
      domain: req.domain,
      prior_failures: req.prior_failures,
      valid,
      errors,
      warnings,
      error_message: valid ? null : 'Research validation failed: ' + errors.join('; '),
      analysis: valid ? parsed : null,
      signals,
      raw_response: raw,
      usage,
    },
  });
}

return out;
